public static void serverSideCancelCast(ServerPlayer serverPlayer, boolean triggerCooldown) {
    CancelCastPacket.cancelCast(serverPlayer, triggerCooldown);
}

public static void cancelCast(ServerPlayer serverPlayer, boolean triggerCooldown) {
    if (serverPlayer != null) {
        var playerMagicData = MagicData.getPlayerMagicData(serverPlayer);
        if (playerMagicData.isCasting()) {
            var spellData = playerMagicData.getCastingSpell();

            if (triggerCooldown) {
                MagicHelper.MAGIC_MANAGER.addCooldown(serverPlayer, spellData.getSpell(), playerMagicData.getCastSource());
            }
            if (playerMagicData.getCastSource() == CastSource.SCROLL && spellData.getSpell().getCastType() == CastType.CONTINUOUS) {
                Scroll.attemptRemoveScrollAfterCast(serverPlayer);
            }
            playerMagicData.getCastingSpell().getSpell().onServerCastComplete(serverPlayer.level, spellData.getLevel(), serverPlayer, playerMagicData, true);
        }
    }
}

public void onServerCastComplete(Level level, int spellLevel, LivingEntity entity, MagicData playerMagicData, boolean cancelled) {
    if (Log.SPELL_DEBUG) {
        IronsSpellbooks.LOGGER.debug("AbstractSpell.onServerCastComplete isClient:{}, spell{}({}), pmd:{}, cancelled:{}", level.isClientSide, getSpellId(), spellLevel, playerMagicData, cancelled);
    }

    playerMagicData.resetCastingState();
    if (entity instanceof ServerPlayer serverPlayer) {
        PacketDistributor.sendToPlayersTrackingEntityAndSelf(serverPlayer, new io.redspace.ironsspellbooks.network.casting.OnCastFinishedPacket(serverPlayer.getUUID(), getSpellId(), cancelled));
    }
}

private void ars_nouveau$setSecondsOnFire(int pRemainingFireTicks, CallbackInfo ci) {
    if (((Entity) (Object) this) instanceof LivingEntity livingEntity && isWet(livingEntity) && pRemainingFireTicks > 0) {
        livingEntity.clearFire();
        ci.cancel();
    }
}

private static boolean isWet(LivingEntity livingEntity) {
    return livingEntity.hasEffect(ModPotions.SOAKED_EFFECT) || livingEntity.getVehicle() instanceof BubbleEntity;
}

private boolean ars_nouveau$isInWaterOrRain(boolean original) {
    if (((Entity) (Object) this) instanceof LivingEntity livingEntity && isWet(livingEntity)) {
        return true;
    }
    return original;
}

public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    Entity entity = rayTraceResult.getEntity();
    if (entity.isOnFire()) {
        entity.clearFire();
    }
    if (entity instanceof LivingEntity livingEntity && spellStats.getDurationMultiplier() > 0) {
        applyConfigPotion(livingEntity, ModPotions.SOAKED_EFFECT, spellStats);
    }
    if (spellStats.isSensitive() && !world.dimensionType().ultraWarm()) {
        placeWater((ServerLevel) world, shooter, spellContext, resolver, entity.blockPosition(), Direction.UP);
    }

}

package com.hollingsworth.arsnouveau.api.spell;

import net.minecraft.core.Holder;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.entity.LivingEntity;

public interface IPotionEffect {

    default void applyConfigPotion(LivingEntity entity, Holder<MobEffect> potionEffect, SpellStats spellStats) {
        applyConfigPotion(entity, potionEffect, spellStats, true);
    }

    default void applyConfigPotion(LivingEntity entity, Holder<MobEffect> potionEffect, SpellStats spellStats, boolean showParticles) {
        applyPotion(entity, potionEffect, spellStats, getBaseDuration(), getExtendTimeDuration(), showParticles);
    }

    default void applyPotion(LivingEntity entity, Holder<MobEffect> potionEffect, SpellStats stats, int baseDurationSeconds, int durationBuffSeconds, boolean showParticles) {
        if (entity == null)
            return;
        int ticks = baseDurationSeconds * 20 + durationBuffSeconds * stats.getDurationInTicks();
        int amp = (int) stats.getAmpMultiplier();
        entity.addEffect(new MobEffectInstance(potionEffect, ticks, amp, false, showParticles, true));
    }

    int getBaseDuration();

    int getExtendTimeDuration();
}

package com.hollingsworth.arsnouveau.common.potions;

import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.world.effect.MobEffect;
import net.minecraft.world.effect.MobEffectCategory;
import net.minecraft.world.entity.LivingEntity;
import org.jetbrains.annotations.NotNull;

public class SoakedEffect extends MobEffect {

    public SoakedEffect() {
        super(MobEffectCategory.NEUTRAL, 0x0000FF, ParticleTypes.DRIPPING_WATER);
    }

    @Override
    public boolean applyEffectTick(@NotNull LivingEntity living, int amplifier) {
        super.applyEffectTick(living, amplifier);
        if (living.isOnFire()) {
            living.clearFire();
        }
        return true;
    }

}

public void onResolveEffect(Level world, HitResult result) {
    if (world.isClientSide) {
        return;
    }
    this.hitResult = result;
    this.resolveAllEffects(world);
}

protected void resolveAllEffects(Level world) {
    if (world.isClientSide) {
        return;
    }
    spellContext.resetCastCounter();
    resume(world);
}

public void onClientReceived(Minecraft mc, Player player) {
    if (mc.level.getEntity(this.entity) instanceof LivingEntity living && living != ArsNouveau.proxy.getPlayer()) {
        Holder<MobEffect> effect = BuiltInRegistries.MOB_EFFECT.getHolder(this.effect).orElse(null);
        if (effect == null) return;
        if (duration > 0) {
            living.addEffect(new MobEffectInstance(effect, duration, 0, false, false, false));
        } else {
            living.removeEffect(effect);
        }
    }
}

