@Mixin(ServerWorld.class)
public abstract class ServerWorldMixin implements WorldScheduler {

    // MARK: WorldScheduler

    @Override
    public long getSchedulerTime() {
        return ((World)((Object)this)).getTime();
    }

    private Map<Long, List<Runnable>> scheduledTasks = new HashMap<>();
    @Override public Map<Long, List<Runnable>> getScheduledTasks() {
        return scheduledTasks;
    }

    private ArrayList<Runnable> immediateTasks = new ArrayList<>();
    @Override public ArrayList<Runnable> getImmediateTasks() {
        return immediateTasks;
    }

    @Inject(method = "tick", at = @At("TAIL"))
    private void tick_TAIL_SpellEngine(BooleanSupplier shouldKeepTicking, CallbackInfo ci) {
        updateScheduledTasks();
    }


}

protected void onHitEntity(EntityHitResult entityHitResult) {
    var entity = getOwner();
    var resultEntity = entityHitResult.getEntity();
    if (entity != null && resultEntity instanceof LivingEntity target && target.distanceToSqr(entity) < range * range) {
        if (!DamageSources.isFriendlyFireBetween(entity, target)) {
            var knockback = new Vec3(entity.getX() - target.getX(), entity.getY() - target.getY(), entity.getZ() - target.getZ()).normalize().scale(-strength);
            target.setDeltaMovement(target.getDeltaMovement().add(knockback));
            target.hurtMarked = true;
            target.addEffect(new MobEffectInstance(MobEffectRegistry.AIRBORNE, 60, amplifier));
        }
    }
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    float range = getRange(spellLevel, entity);
    float strength = getStrength(spellLevel, entity);

    GustCollider gust = new GustCollider(level, entity);
    gust.setPos(entity.position().add(0, entity.getEyeHeight() * .7, 0).add(entity.getForward().normalize().scale(2f)));
    gust.range = range;
    gust.strength = strength;
    gust.amplifier = spellLevel - 1;
    level.addFreshEntity(gust);
    gust.setDealDamageActive();
    gust.tick();

    float kickback = (float) entity.getBoundingBox().getCenter().distanceToSqr(Utils.getTargetBlock(level, entity, ClipContext.Fluid.NONE, 3.5f).getLocation());
    kickback = Mth.clamp(1 / (kickback + 1) - .11f, 0f, .95f);
    if (kickback > 0) {
        entity.setDeltaMovement(entity.getDeltaMovement().subtract(entity.getLookAngle().scale(kickback * spellLevel * .25f)));
        entity.resetFallDistance();
        entity.hurtMarked = true;
    }
    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

public void tick() {
    super.tick();

    if (++age > FAILSAFE_EXPIRE_TIME) {
        //This exists in case there is any bug with removing the cone onCastComplete
        discard();
    }

    //TODO: try this instead of the ray trace
    /*
    So. This is what vectors are for.
    The player has a vector that is their "front" called "LookVec" (Search the EntityPlayer class).
    Take that vector, multiply by 0.5 (or 0.2 or whatever), add their current position, and voila. You have the spot a half-block in front of them.
    */

    var owner = this.getOwner();
    if (owner != null) {
        var rayTraceVector = rayTrace(owner);
        var ownerEyePos = owner.getEyePosition(1.0f).subtract(0, .8, 0);
        this.setPos(ownerEyePos);
        this.setXRot(owner.getXRot());
        this.setYRot(owner.getYRot());
        this.yRotO = getYRot();
        this.xRotO = getXRot();
        //setDeltaMovement(ownerEyePos);

        double scale = 1;

        for (int i = 0; i < subEntities.length; i++) {
            var subEntity = subEntities[i];

            double distance = 1 + (i * scale * subEntity.getDimensions(null).width() / 2);
            Vec3 newVector = ownerEyePos.add(rayTraceVector.multiply(distance, distance, distance));
            subEntity.setPos(newVector);
            subEntity.setDeltaMovement(newVector);
            var vec3 = new Vec3(subEntity.getX(), subEntity.getY(), subEntity.getZ());
            subEntity.xo = vec3.x;
            subEntity.yo = vec3.y;
            subEntity.zo = vec3.z;
            subEntity.xOld = vec3.x;
            subEntity.yOld = vec3.y;
            subEntity.zOld = vec3.z;
        }
    }

    /* Hit Detection */
    if (!level.isClientSide) {
        if (dealDamageActive) {
            for (Entity entity : getSubEntityCollisions()) {
                //irons_spellbooks.LOGGER.debug("ConeOfColdHit : {}", entity.getName().getString());
                onHitEntity(new EntityHitResult(entity));
            }
            dealDamageActive = false;
        }
    } else {
        spawnParticles();
    }

}

protected Set<Entity> getSubEntityCollisions() {
    List<Entity> collisions = new ArrayList<>();
    for (Entity conepart : subEntities) {
        collisions.addAll(level().getEntities(conepart, conepart.getBoundingBox()));
    }

    return collisions.stream().filter(target ->
            target != getOwner() && target instanceof LivingEntity && Utils.hasLineOfSight(level, this, target, true)
    ).collect(Collectors.toSet());
}

public Entity getOwner() {
    if (tickCount >= 1)
        return null;
    return super.getOwner();
}

public void tick() {
    double x = getX();
    double y = getY();
    double z = getZ();
    if (tickCount > 8)
        discard();
    else
        super.tick();
    setPosRaw(x, y, z);
}

public boolean applyEffectTick(LivingEntity livingEntity, int pAmplifier) {
    if (!livingEntity.level.isClientSide) {
        if (livingEntity.horizontalCollision) {
            double d11 = livingEntity.getDeltaMovement().horizontalDistance();
            float f1 = (float) (d11 * 10.0D - 1.0D);
            //IronsSpellbooks.LOGGER.debug("AirborneEffect horizontalCollision: {}, {}", livingEntity.getDeltaMovement().horizontalDistance(),f1);
            if (f1 > 0.0F) {
                livingEntity.playSound(SoundEvents.HOSTILE_BIG_FALL, 2.0F, 1.5F);
                livingEntity.hurt(livingEntity.damageSources().flyIntoWall(), getDamageFromLevel(pAmplifier + 1));
                return false;
            }
        }
    }
    return true;
}

public boolean shouldApplyEffectTickThisTick(int pDuration, int pAmplifier) {
    return true;
}

public static void performTaunt(LivingEntity newTarget, List<Entity> targets) {
    targets.forEach(entity -> {
        if (entity instanceof Mob tauntmob) {
            MagicManager.spawnParticles(tauntmob.level, ParticleTypes.ANGRY_VILLAGER, tauntmob.getX(), tauntmob.getEyeY() + (tauntmob.getBoundingBox().maxY - tauntmob.getEyeY()) * 2, tauntmob.getZ(), 5, 0.3, 0.3, 0.3, 0, false);
            tauntmob.setTarget(newTarget);
        }
    });
}

public static void performTaunt(LivingEntity newTarget, float range, Predicate<Entity> selector) {
    performTaunt(newTarget, newTarget.level.getEntities(newTarget, newTarget.getBoundingBox().inflate(range, range, range),
            entity -> entity.distanceToSqr(newTarget) < range * range && selector.test(entity)));
}

public static Predicate<Entity> tauntPredicate(Entity taunter) {
    return entity -> (entity instanceof Enemy ^ taunter instanceof Enemy && !taunter.isAlliedTo(entity))
            || ((taunter instanceof LivingEntity livingEntity && entity instanceof NeutralMob neutralMob) && neutralMob.isAngryAt(livingEntity));
}

public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
    Vec3 targetPos = Utils.moveToRelativeGroundLevel(world, Utils.raycastForBlock(world, entity.getEyePosition(), entity.getEyePosition().add(entity.getForward().scale(getRange(spellLevel, entity))), ClipContext.Fluid.NONE).getLocation(), 4, 24);
    ScapegoatEntity goat = new ScapegoatEntity(world);
    goat.setOwner(entity);
    goat.setTargetPos(BlockPos.containing(targetPos));
    float y = entity.getYRot();
    goat.setYBodyRot(y);
    goat.yBodyRotO = y;
    goat.setYRot(y);
    goat.yRotO = y;
    goat.yHeadRot = y;
    goat.yHeadRotO = y;
    //todo: clip?
    goat.moveTo(entity.getEyePosition().add(entity.getForward().scale(2)));
    goat.getAttributes().getInstance(Attributes.MAX_HEALTH).setBaseValue(getGoatHealth(spellLevel, entity));
    goat.setHealth(goat.getMaxHealth());
    goat.poofParticles(20, 1f);
    // todo: expose to tootip/power scaling?
    goat.setDurationRemaining(20 * 15);
    goat.invulnerableTime = 60;
    world.addFreshEntity(goat);
    Utils.performTaunt(goat, 12f, Utils.tauntPredicate(entity));
}

